"""Totals and filtering over parsed entries."""

from decimal import Decimal


def balance(entries):
    """Total of all amounts as a Decimal (zero for no entries)."""
    total = Decimal(0)
    for entry in entries:
        total += entry.amount
    return total


def _group(entries, key):
    totals = {}
    for entry in entries:
        k = key(entry)
        totals[k] = totals.get(k, Decimal(0)) + entry.amount
    return {k: totals[k] for k in sorted(totals)}


def by_category(entries):
    """dict of category -> total, keys sorted."""
    return _group(entries, lambda e: e.category)


def by_month(entries):
    """dict of ``"YYYY-MM"`` -> total, keys sorted."""
    return _group(entries, lambda e: "%04d-%02d" % (e.date.year, e.date.month))


def filter_entries(entries, category=None, since=None, until=None):
    """Matching entries in input order. ``None`` means no filter; bounds are inclusive."""
    if category is not None:
        category = category.lower()
    result = []
    for entry in entries:
        if category is not None and entry.category != category:
            continue
        if since is not None and entry.date < since:
            continue
        if until is not None and entry.date > until:
            continue
        result.append(entry)
    return result
"""Ledger entries and the parser for the plain-text ledger format."""

import datetime
import re
from dataclasses import dataclass
from decimal import Decimal, localcontext

_DATE_RE = re.compile(r"\d{4}-\d{2}-\d{2}", re.ASCII)
_AMOUNT_RE = re.compile(r"[+-]?\d+(\.\d{1,2})?", re.ASCII)
_SEPARATOR_RE = re.compile(r"[ \t]+")
_TWO_PLACES = Decimal("0.01")


@dataclass(frozen=True)
class Entry:
    """One ledger line."""

    date: datetime.date
    category: str
    amount: Decimal
    note: str = ""


class ParseError(ValueError):
    """A line of the ledger is not valid. ``line`` is its 1-based number."""

    def __init__(self, line, message):
        super().__init__("line %d: %s" % (line, message))
        self.line = line
        self.message = message

    def __reduce__(self):
        return (type(self), (self.line, self.message))


def _parse_date(text):
    if not _DATE_RE.fullmatch(text):
        raise ValueError("invalid date %r (expected YYYY-MM-DD)" % text)
    try:
        return datetime.date(int(text[0:4]), int(text[5:7]), int(text[8:10]))
    except ValueError:
        raise ValueError("invalid date %r (no such day)" % text) from None


def _parse_amount(text):
    if not _AMOUNT_RE.fullmatch(text):
        raise ValueError(
            "invalid amount %r (expected a number with at most two decimals)" % text
        )
    return Decimal(text)


def parse(text):
    """Parse ledger text into a list of :class:`Entry`, in file order.

    Raises :class:`ParseError` for the first bad line.
    """
    entries = []
    lines = text.replace("\r\n", "\n").replace("\r", "\n").split("\n")
    for number, raw in enumerate(lines, start=1):
        stripped = raw.strip()
        if not stripped or stripped.startswith("#"):
            continue
        fields = _SEPARATOR_RE.split(stripped, maxsplit=3)
        if len(fields) < 3:
            raise ParseError(
                number, "expected DATE CATEGORY AMOUNT [NOTE], got %d field(s)" % len(fields)
            )
        try:
            date = _parse_date(fields[0])
            amount = _parse_amount(fields[2])
        except ValueError as exc:
            raise ParseError(number, str(exc)) from None
        note = fields[3] if len(fields) > 3 else ""
        entries.append(Entry(date, fields[1].lower(), amount, note))
    return entries


def format_amount(amount):
    """Format a Decimal with exactly two decimals (negative zero prints as 0.00)."""
    with localcontext() as ctx:
        ctx.prec = max(ctx.prec, amount.adjusted() + 6) if amount.is_finite() else ctx.prec
        quantized = amount.quantize(_TWO_PLACES)
    if quantized == 0:
        quantized = abs(quantized)
    return format(quantized, "f")


def format_entry(entry):
    """Format an entry as ``DATE CATEGORY AMOUNT[ NOTE]``."""
    line = "%s %s %s" % (entry.date.isoformat(), entry.category, format_amount(entry.amount))
    if entry.note:
        line += " " + entry.note
    return line
